SELECT * FROM tw_team_event_log
WHERE team_id = #{teamId}

    AND event_type = #{eventType}


    AND operator_username LIKE CONCAT('%', #{operatorKeyword}, '%')


    AND affected_username LIKE CONCAT('%', #{affectedKeyword}, '%')


    AND invite_code LIKE CONCAT('%', #{inviteCode}, '%')


    AND created_at  >=  #{startTime}


    AND created_at  <=  #{endTime}

ORDER BY created_at DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM tw_team_event_log
WHERE team_id = #{teamId}

    AND event_type = #{eventType}


    AND operator_username LIKE CONCAT('%', #{operatorKeyword}, '%')


    AND affected_username LIKE CONCAT('%', #{affectedKeyword}, '%')


    AND invite_code LIKE CONCAT('%', #{inviteCode}, '%')


    AND created_at  >=  #{startTime}


    AND created_at  <=  #{endTime}

SELECT * FROM tw_team_event_log
WHERE team_id = #{teamId}
  AND event_type = 'member_join'
  AND invite_code_id = #{inviteCodeId}
ORDER BY created_at DESC
